TELA_2_CENTRAL_DE_CONTROLE.PAGEHEADER_CODIGO_REACT_COMPLETO_COPIE:
function PageHeader({ scoreNum = 87, scoreStatus = 'ok', scoreLabel = 'Operação saudável' }) {
  const colorMap = { ok: '#10b981', warning: '#f59e0b', critical: '#ef4444' };
  const gradMap = {
    ok: 'linear-gradient(135deg,#10b981,#06b6d4)',
    warning: 'linear-gradient(135deg,#f59e0b,#ef8c3b)',
    critical: 'linear-gradient(135deg,#ef4444,#ec4899)',
  };
  const color = colorMap[scoreStatus];
  const grad = gradMap[scoreStatus];
  return (
    <div style={{
      background: `linear-gradient(rgba(15,15,35,.92),rgba(15,15,35,.92)) padding-box, ${grad} border-box`,
      border: '1px solid transparent', borderRadius: 16, padding: 28, marginBottom: 22,
      boxShadow: '0 8px 40px rgba(0,0,0,.55)', backdropFilter: 'blur(12px)',
    }}>
      <div style={{ display: 'grid', gridTemplateColumns: 'auto 1fr auto', gap: 22, alignItems: 'center' }}>
        <BrainBadge color={color} />
        <div style={{ minWidth: 0 }}>
          <div style={{
            fontSize: 16, fontWeight: 800, textTransform: 'uppercase', letterSpacing: '0.12em',
            background: grad, WebkitBackgroundClip: 'text', WebkitTextFillColor: 'transparent', backgroundClip: 'text',
            marginBottom: 6,
          }}>Central de Controle</div>
          <h1 style={{ margin: 0, color: '#f1f5f9', fontSize: 34, lineHeight: 1.05, fontWeight: 800 }}>
            Score Operacional <span style={{ color, fontVariantNumeric: 'tabular-nums' }}>{scoreNum}</span>
            <span style={{ color: '#475569', fontSize: 22, fontWeight: 600 }}>/100</span>
          </h1>
          <div style={{ display: 'flex', gap: 14, alignItems: 'center', marginTop: 10, flexWrap: 'wrap' }}>
            <span style={{ display: 'inline-flex', alignItems: 'center', gap: 8 }}>
              <PulseDot color={color} />
              <span style={{ color: '#f1f5f9', fontSize: 14, fontWeight: 700 }}>{scoreLabel}</span>
            </span>
            <span style={{ color: '#94a3b8', fontSize: 12 }}>Atualizado em 09/06/2026 12:47</span>
          </div>
        </div>
        <div style={{ display: 'flex', gap: 10, flexWrap: 'wrap', justifyContent: 'flex-end' }}>
          <button style={{
            background: 'linear-gradient(135deg,#7c3aed,#06b6d4)', color: '#fff', border: 'none',
            borderRadius: 10, padding: '12px 24px', cursor: 'pointer', fontSize: 15, fontWeight: 600,
            boxShadow: '0 4px 14px rgba(0,0,0,.35)',
          }}>↻ Atualizar diagnóstico</button>
          <button style={{
            background: 'linear-gradient(135deg,#6d28d9,#7c3aed)', color: '#fff', border: 'none',
            borderRadius: 10, padding: '12px 24px', cursor: 'pointer', fontSize: 15, fontWeight: 600,
          }}>⚡ Auditar Meta ao vivo</button>
        </div>
      </div>
      <div style={{ marginTop: 18 }}>
        <GradientBar pct={scoreNum} gradient={grad} height={8} />
      </div>
    </div>
  );
}

